const STORE_KEY = 'shiftly-data-v1';
const THEME_KEY = 'shiftly-theme';
const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => [...document.querySelectorAll(selector)];
const today = new Date();
const dateInputValue = (date) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const initial = { shifts: [], expenses: [], incomeEntries: [], payslips: [], bills: [], categoryBudgets: {}, reminderPrefs: { billDue: true, longShift: true }, workplaces: [], shiftTemplates: [], activeClock: null, defaultWorkplaceId: '', workplace: '', rate: 450 };
let data;
try { data = { ...initial, ...JSON.parse(localStorage.getItem(STORE_KEY) || '{}') }; } catch { data = { ...initial }; }
if (!Array.isArray(data.shifts)) data.shifts = [];
if (!Array.isArray(data.expenses)) data.expenses = [];
if (!Array.isArray(data.incomeEntries)) data.incomeEntries = [];
if (!Array.isArray(data.payslips)) data.payslips = [];
if (!Array.isArray(data.bills)) data.bills = [];
if (!data.categoryBudgets || typeof data.categoryBudgets!=='object' || Array.isArray(data.categoryBudgets)) data.categoryBudgets={};
if (!data.reminderPrefs || typeof data.reminderPrefs!=='object') data.reminderPrefs={...initial.reminderPrefs};
if (!Array.isArray(data.workplaces)) data.workplaces = [];
if (!Array.isArray(data.shiftTemplates)) data.shiftTemplates = [];
if (!data.workplaces.length && data.workplace) data.workplaces.push({ id: crypto.randomUUID(), name: data.workplace, rate: Number(data.rate) || 450 });
for (const shift of data.shifts) {
  let workplace = data.workplaces.find(x => x.id === shift.workplaceId) || data.workplaces.find(x => x.name === shift.workplace);
  if (!workplace && shift.workplace) { workplace = { id: crypto.randomUUID(), name: shift.workplace, rate: Number(shift.rate) || 450 }; data.workplaces.push(workplace); }
  if (workplace) shift.workplaceId = workplace.id;
}
if (data.workplaces.length && !data.workplaces.some(x => x.id === data.defaultWorkplaceId)) data.defaultWorkplaceId = data.workplaces[0].id;
const storedDefaultWorkplace = data.workplaces.find(x => x.id === data.defaultWorkplaceId);
if (storedDefaultWorkplace) { data.workplace = storedDefaultWorkplace.name; data.rate = storedDefaultWorkplace.rate; }
let activePage = 'home';
let entryType = 'shift';
let editRecordId = null;
let editingWorkplaceId = null;
let editingPayslipId = null;
let editingBillId = null;
let pendingOverlapKey = null;
let clockOutPending = false;
let toastTimer;
let supabaseClient = null;
let cloudUser = null;
let cloudBaseline = { workplaces: [], shifts: [], expenses: [], incomeEntries: [], payslips: [], bills: [], shiftTemplates: [] };
let templatesCloudAvailable = true;
let incomeCloudAvailable = true;
let payslipsCloudAvailable = true;
let billsCloudAvailable = true;
let cloudSyncBusy = false;
let cloudSyncQueued = false;
let cloudAuthMode = 'signin';

function save() { localStorage.setItem(STORE_KEY, JSON.stringify(data)); if(cloudUser)queueCloudSync(); }
function money(value) { return 'Rs. ' + Math.round(Number(value) || 0).toLocaleString('en-LK'); }
function parseDay(value) { const [y,m,d] = value.split('-').map(Number); return new Date(y,m-1,d); }
function prettyDate(value, includeYear=false) { return parseDay(value).toLocaleDateString('en-LK',{day:'numeric',month:'short',...(includeYear?{year:'numeric'}:{})}); }
function weekStartFor(value) { const date=parseDay(value),offset=(date.getDay()+6)%7;date.setDate(date.getDate()-offset);return dateInputValue(date); }
function weekRangeLabel(start) { const end=parseDay(start);end.setDate(end.getDate()+6);return `${prettyDate(start)} – ${prettyDate(dateInputValue(end))}`; }
function monthKey(date=today) { return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`; }
function selectedMonth() { return $('#month-select').value || monthKey(); }
function isCurrentMonth(date) { return date.startsWith(selectedMonth()); }
function monthDates(key) { const [y,m]=key.split('-').map(Number); return {start:`${y}-${String(m).padStart(2,'0')}-01`,end:`${y}-${String(m).padStart(2,'0')}-${String(new Date(y,m,0).getDate()).padStart(2,'0')}`}; }
function shiftDuration(shift) { const [sh,sm]=shift.start.split(':').map(Number),[eh,em]=shift.end.split(':').map(Number); let mins=eh*60+em-(sh*60+sm); if(mins<0) mins+=1440; return Math.max(0,mins-(Number(shift.breakMinutes)||0)); }
function shiftHours(shift) { return shiftDuration(shift)/60; }
function shiftPay(shift) { return Math.round((shiftDuration(shift)/60)*(Number(shift.rate)||0)+(Number(shift.tips)||0)); }
function shiftBounds(shift) { const start=parseDay(shift.date),end=parseDay(shift.date),[sh,sm]=shift.start.split(':').map(Number),[eh,em]=shift.end.split(':').map(Number);start.setHours(sh,sm,0,0);end.setHours(eh,em,0,0);if(end<=start)end.setDate(end.getDate()+1);return {start:start.getTime(),end:end.getTime()}; }
function findOverlappingShift(candidate) { const bounds=shiftBounds(candidate);return data.shifts.find(shift=>shift.id!==editRecordId&&(()=>{const other=shiftBounds(shift);return bounds.start<other.end&&other.start<bounds.end;})()); }
function formatHours(hours) { return Number.isInteger(hours)?String(hours):hours.toFixed(1); }
function calcPreview() { const date=$('#shift-date').value,start=$('#start-time').value,end=$('#end-time').value,rate=Number($('#rate').value)||0,br=Number($('#break-minutes').value)||0,tips=Number($('#tips').value)||0; if(!date||!start||!end) { $('#pay-preview').textContent=money(0); return; } let mins=shiftDuration({start,end,breakMinutes:br}); $('#pay-preview').textContent=money(Math.round(mins/60*rate+tips)); }
function setPage(page) { activePage=page; $$('.page').forEach(el=>el.classList.toggle('hidden',el.id!==`page-${page}`)); $$('.nav-item,.mobile-tabs button').forEach(el=>el.classList.toggle('active',el.dataset.page===page)); $('#crumb').textContent=page.charAt(0).toUpperCase()+page.slice(1); if(page==='shifts') renderShifts(); if(page==='expenses') renderExpenses();if(page==='bills')renderBills();if(page==='insights'){renderIncomeEntries();renderPayslips();} window.scrollTo({top:0,behavior:'smooth'}); }
function toast(message, undo=null) { const el=$('#toast'); el.replaceChildren(document.createTextNode(message)); if(undo){const button=document.createElement('button');button.className='toast-undo';button.textContent='Undo';button.addEventListener('click',()=>{undo();el.classList.remove('visible');});el.append(button);} el.classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('visible'),4500); }
function createMonthOptions() { const select=$('#month-select'), start=new Date(today.getFullYear(),today.getMonth()-11,1); for(let i=0;i<18;i++){const d=new Date(start.getFullYear(),start.getMonth()+i,1),opt=document.createElement('option'); opt.value=monthKey(d);opt.textContent=d.toLocaleDateString('en-LK',{month:'long',year:'numeric'});select.append(opt);} select.value=monthKey(); }
function monthData() { const shifts=data.shifts.filter(x=>isCurrentMonth(x.date)),expenses=data.expenses.filter(x=>isCurrentMonth(x.date)),incomeEntries=data.incomeEntries.filter(x=>isCurrentMonth(x.date)); const hours=shifts.reduce((sum,x)=>sum+shiftHours(x),0),income=shifts.reduce((sum,x)=>sum+shiftPay(x),0)+incomeEntries.reduce((sum,x)=>sum+Number(x.amount),0),spent=expenses.reduce((sum,x)=>sum+Number(x.amount),0);return {shifts,expenses,incomeEntries,hours,income,spent}; }
function renderDashboard() {
 const d=monthData(); $('#hours-total').textContent=formatHours(d.hours);$('#shift-count').textContent=`${d.shifts.length} ${d.shifts.length===1?'shift':'shifts'}`;$('#income-total').textContent=money(d.income);$('#expense-total').textContent=money(d.spent);$('#expense-count').textContent=`${d.expenses.length} ${d.expenses.length===1?'expense':'expenses'}`;$('#balance-total').textContent=money(d.income-d.spent);$('#expense-progress').style.width=`${d.income?Math.min(100,d.spent/d.income*100):0}%`;
 $('#insight-income').textContent=money(d.income);$('#insight-expense').textContent=money(d.spent);$('#insight-hours').textContent=`${formatHours(d.hours)} hrs`;renderCategoryBreakdown(d.expenses,d.spent);renderBudgets(d.expenses);renderIncomeExpenseChart();
 renderClockAction();renderUpcomingBills();renderReminders();const items=[...d.shifts.map(x=>({...x,kind:'shift',amount:shiftPay(x)})),...d.expenses.map(x=>({...x,kind:'expense'})),...d.incomeEntries.map(x=>({...x,kind:'income'}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5); const list=$('#activity-list');
 if(!items.length){list.innerHTML='<div class="empty-state"><div class="empty-icon">✦</div><b>Your story starts here</b>Log a shift or expense to see your activity.</div>';return;}
 list.innerHTML=items.map(x=>x.kind==='shift'?`<div class="activity-row"><span class="activity-icon shift">◷</span><div class="activity-description"><b>${escapeHtml(x.workplace||'Work shift')}</b><small>${prettyDate(x.date)} · ${formatHours(shiftHours(x))} hrs</small></div><span class="activity-amount income">+ ${money(x.amount)}</span></div>`:x.kind==='income'?`<div class="activity-row"><span class="activity-icon shift">↗</span><div class="activity-description"><b>${escapeHtml(x.type)}</b><small>${prettyDate(x.date)}${x.note?' · '+escapeHtml(x.note):''}</small></div><span class="activity-amount income">+ ${money(x.amount)}</span></div>`:`<div class="activity-row"><span class="activity-icon expense">↘</span><div class="activity-description"><b>${escapeHtml(x.category)}</b><small>${prettyDate(x.date)}${x.note?' · '+escapeHtml(x.note):''}</small></div><span class="activity-amount spent">− ${money(x.amount)}</span></div>`).join('');
}
function renderClockAction(){const clock=data.activeClock,button=$('#clock-action'),title=$('#clock-action-title'),detail=$('#clock-action-detail');if(!button)return;if(clock){const started=new Date(clock.startedAt),minutes=Math.max(0,Math.floor((Date.now()-started.getTime())/60000)),w=data.workplaces.find(x=>x.id===clock.workplaceId);title.textContent=`Clocked in · ${Math.floor(minutes/60)}h ${String(minutes%60).padStart(2,'0')}m`;detail.textContent=`${w?.name||'Work shift'} · Started ${clock.time}`;button.classList.add('clock-running');button.querySelector('.quick-icon').textContent='■';button.querySelector('.action-arrow').textContent='↘';}else{title.textContent='Clock in';detail.textContent='Start a shift timer';button.classList.remove('clock-running');button.querySelector('.quick-icon').textContent='◷';button.querySelector('.action-arrow').textContent='↗';}}
function localTimeParts(date=new Date()){return {date:dateInputValue(date),time:`${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`};}
function toggleClock(){if(!data.activeClock){const workplace=data.workplaces.find(w=>w.id===data.defaultWorkplaceId)||data.workplaces[0];if(!workplace){setPage('settings');toast('Add a workplace before clocking in');return;}const now=new Date(),parts=localTimeParts(now);data.activeClock={startedAt:now.toISOString(),date:parts.date,time:parts.time,workplaceId:workplace.id};save();renderDashboard();toast(`Clocked in at ${parts.time}`);return;}clockOutPending=true;const parts=localTimeParts();openEntry('shift');$('#shift-date').value=data.activeClock.date;$('#workplace').value=data.activeClock.workplaceId;const workplace=data.workplaces.find(w=>w.id===data.activeClock.workplaceId);if(workplace)$('#rate').value=workplace.rate;$('#start-time').value=data.activeClock.time;$('#end-time').value=parts.time;$('#shift-note').value='';calcPreview();$('#dialog-title').textContent='Review your shift';$('#form-eyebrow').textContent='CLOCK OUT · CHECK YOUR HOURS';$('#save-entry').innerHTML='Save shift <span>→</span>';}
function renderCategoryBreakdown(expenses,total){const totals=new Map();for(const expense of expenses){const category=expense.category||'Other';const current=totals.get(category)||{amount:0,count:0};current.amount+=Number(expense.amount)||0;current.count++;totals.set(category,current);}const rows=[...totals.entries()].sort((a,b)=>b[1].amount-a[1].amount),container=$('#category-breakdown');if(!rows.length){container.innerHTML='<div class="empty-state compact-empty">Add expenses to see your spending categories.</div>';return;}container.innerHTML=rows.map(([category,summary])=>`<div class="category-row"><div class="category-name"><b>${escapeHtml(category)}</b><small>${summary.count} ${summary.count===1?'entry':'entries'}</small></div><div class="category-bar"><span style="width:${total?Math.max(3,summary.amount/total*100):0}%"></span></div><strong>${money(summary.amount)}</strong></div>`).join('');}
function renderBudgets(expenses){const list=$('#budget-list');if(!list)return;const totals=new Map();for(const expense of expenses){const category=expense.category||'Other';totals.set(category,(totals.get(category)||0)+Number(expense.amount||0));}const budgets=Object.entries(data.categoryBudgets).filter(([,amount])=>Number.isInteger(Number(amount))&&Number(amount)>0).sort((a,b)=>a[0].localeCompare(b[0]));if(!budgets.length){list.innerHTML='<div class="empty-state compact-empty">No monthly limits yet. Choose a category and set a spending limit.</div>';return;}list.innerHTML=budgets.map(([category,limit])=>{const spent=totals.get(category)||0,pct=Math.min(100,spent/Number(limit)*100),over=spent>Number(limit);return `<div class="budget-row ${over?'over-budget':''}"><div class="budget-title"><b>${escapeHtml(category)}</b><span>${over?'Over by '+money(spent-Number(limit)):money(Number(limit)-spent)+' left'}</span></div><div class="budget-track"><span style="width:${pct}%"></span></div><div class="budget-meta"><span>${money(spent)} spent</span><span>of ${money(Number(limit))}</span><button class="row-delete" type="button" data-budget-remove="${escapeHtml(category)}" aria-label="Remove ${escapeHtml(category)} budget">×</button></div></div>`;}).join('');}
function saveBudget(event){event.preventDefault();const category=$('#budget-category').value,limit=Number($('#budget-limit').value);if(!category||!Number.isInteger(limit)||limit<1)return;data.categoryBudgets[category]=limit;save();$('#budget-limit').value='';renderBudgets(monthData().expenses);toast('Monthly limit saved');}
$('#budget-form').addEventListener('submit',saveBudget);$('#budget-list').addEventListener('click',event=>{const button=event.target.closest('[data-budget-remove]');if(!button)return;delete data.categoryBudgets[button.dataset.budgetRemove];save();renderBudgets(monthData().expenses);});
function renderIncomeExpenseChart(){const container=$('#income-expense-chart');if(!container)return;const [year,month]=selectedMonth().split('-').map(Number),months=Array.from({length:6},(_,index)=>{const date=new Date(year,month-1-(5-index),1),key=monthKey(date);const income=data.shifts.filter(x=>x.date.startsWith(key)).reduce((sum,x)=>sum+shiftPay(x),0)+data.incomeEntries.filter(x=>x.date.startsWith(key)).reduce((sum,x)=>sum+Number(x.amount||0),0),spent=data.expenses.filter(x=>x.date.startsWith(key)).reduce((sum,x)=>sum+Number(x.amount||0),0);return {key,label:date.toLocaleDateString('en-LK',{month:'short'}),income,spent};}),max=Math.max(1,...months.flatMap(x=>[x.income,x.spent]));container.innerHTML=months.map(x=>`<div class="chart-row" role="group" aria-label="${x.label} ${x.key.slice(0,4)}: income ${money(x.income)}, spending ${money(x.spent)}"><span class="chart-month">${x.label}</span><div class="chart-bars"><div class="chart-track"><i class="chart-income" style="width:${x.income/max*100}%"></i></div><div class="chart-track"><i class="chart-expense" style="width:${x.spent/max*100}%"></i></div></div><div class="chart-values"><span>${money(x.income)}</span><span>${money(x.spent)}</span></div></div>`).join('');}
function renderIncomeEntries(){const list=$('#income-list');if(!list)return;const entries=data.incomeEntries.filter(x=>isCurrentMonth(x.date)).sort((a,b)=>b.date.localeCompare(a.date));if(!entries.length){list.innerHTML='<div class="empty-state compact-empty">Add tips, service charge, bonuses, or other income to include them in your totals.</div>';return;}list.innerHTML=entries.map(x=>{const workplace=data.workplaces.find(w=>w.id===x.workplaceId);return `<div class="list-entry"><span class="activity-icon shift">↗</span><div class="entry-main"><b>${escapeHtml(x.type.replace('_',' '))}</b><small>${prettyDate(x.date,true)}${workplace?' · '+escapeHtml(workplace.name):''}${x.note?' · '+escapeHtml(x.note):''}</small></div><div class="entry-right"><b>+ ${money(x.amount)}</b><small>Extra income</small></div><button class="row-edit" data-edit-kind="incomeEntries" data-edit-id="${escapeHtml(x.id)}" aria-label="Edit income">Edit</button><button class="row-delete" data-delete-kind="incomeEntries" data-delete-id="${escapeHtml(x.id)}" aria-label="Delete income">×</button></div>`;}).join('');}
function estimatePayslip(payslip){return data.shifts.filter(x=>x.workplaceId===payslip.workplaceId&&x.date>=payslip.periodStart&&x.date<=payslip.periodEnd).reduce((sum,x)=>sum+shiftPay(x),0)+data.incomeEntries.filter(x=>x.workplaceId===payslip.workplaceId&&x.date>=payslip.periodStart&&x.date<=payslip.periodEnd).reduce((sum,x)=>sum+Number(x.amount||0),0);}
function renderPayslips(){const list=$('#payslip-list');if(!list)return;if(!data.payslips.length){list.innerHTML='<div class="empty-state compact-empty">Add a payslip to compare your actual gross pay with shift and extra-income estimates.</div>';return;}list.innerHTML=[...data.payslips].sort((a,b)=>b.periodEnd.localeCompare(a.periodEnd)).map(x=>{const workplace=data.workplaces.find(w=>w.id===x.workplaceId),estimate=estimatePayslip(x),difference=Number(x.gross)-estimate;return `<div class="payslip-row"><div class="payslip-heading"><div><b>${escapeHtml(workplace?.name||'Workplace')}</b><small>${prettyDate(x.periodStart,true)} – ${prettyDate(x.periodEnd,true)}${x.payDate?' · Paid '+prettyDate(x.payDate,true):''}</small></div><div class="payslip-actions"><button class="row-edit" data-payslip-edit="${escapeHtml(x.id)}">Edit</button><button class="row-delete" data-delete-kind="payslips" data-delete-id="${escapeHtml(x.id)}" aria-label="Delete payslip">×</button></div></div><div class="payslip-values"><span>Estimate <b>${money(estimate)}</b></span><span>Actual gross <b>${money(x.gross)}</b></span><span>Net pay <b>${money(x.net)}</b></span><span class="payslip-difference ${difference>=0?'positive':'negative'}">${difference>=0?'Above':'Below'} estimate <b>${difference>=0?'+':'−'} ${money(Math.abs(difference))}</b></span></div>${x.note?`<small class="payslip-note">${escapeHtml(x.note)}</small>`:''}</div>`;}).join('');}
function openPayslip(id=null){if(!data.workplaces.length){toast('Add a workplace before saving a payslip');setPage('settings');return;}editingPayslipId=id;const item=id?data.payslips.find(x=>x.id===id):null;$('#payslip-dialog-title').textContent=item?'Edit payslip':'Add payslip';$('#payslip-workplace').innerHTML=data.workplaces.map(w=>`<option value="${escapeHtml(w.id)}">${escapeHtml(w.name)}</option>`).join('');$('#payslip-workplace').value=item?.workplaceId||data.defaultWorkplaceId||data.workplaces[0].id;$('#payslip-start').value=item?.periodStart||monthDates(selectedMonth()).start;$('#payslip-end').value=item?.periodEnd||monthDates(selectedMonth()).end;$('#payslip-date').value=item?.payDate||'';$('#payslip-gross').value=item?.gross||'';$('#payslip-net').value=item?.net??'';$('#payslip-note').value=item?.note||'';$('#payslip-error').textContent='';$('#payslip-dialog').showModal();}
function savePayslip(event){event.preventDefault();const start=$('#payslip-start').value,end=$('#payslip-end').value,gross=Number($('#payslip-gross').value),net=Number($('#payslip-net').value),error=$('#payslip-error');error.textContent='';if(!start||!end||end<start){error.textContent='Choose a valid pay period.';return;}if(!Number.isInteger(gross)||gross<1||!Number.isInteger(net)||net<0){error.textContent='Enter gross and net pay in whole rupees.';return;}const item={id:editingPayslipId||crypto.randomUUID(),workplaceId:$('#payslip-workplace').value,periodStart:start,periodEnd:end,payDate:$('#payslip-date').value,gross,net,note:$('#payslip-note').value.trim()};if(editingPayslipId){const index=data.payslips.findIndex(x=>x.id===editingPayslipId);if(index>=0)data.payslips[index]=item;}else data.payslips.push(item);editingPayslipId=null;save();$('#payslip-dialog').close();refresh();toast('Payslip saved');}
function nextBillDate(dueDate,frequency,anchorDay,anchorMonth){const date=parseDay(dueDate);if(frequency==='weekly')date.setDate(date.getDate()+7);else if(frequency==='monthly'){const next=new Date(date.getFullYear(),date.getMonth()+1,1),day=anchorDay||date.getDate();next.setDate(Math.min(day,new Date(next.getFullYear(),next.getMonth()+1,0).getDate()));return dateInputValue(next);}else if(frequency==='yearly'){const month=(anchorMonth||date.getMonth()+1)-1,next=new Date(date.getFullYear()+1,month,1),day=anchorDay||date.getDate();next.setDate(Math.min(day,new Date(next.getFullYear(),next.getMonth()+1,0).getDate()));return dateInputValue(next);}else return '';return dateInputValue(date);}
function billOccurrenceId(seriesId,dueDate){const prefix=String(seriesId||crypto.randomUUID()).replaceAll('-','').slice(0,16),[year,month,day]=dueDate.split('-').map(Number),dayNumber=Math.floor(Date.UTC(year,month-1,day)/86400000),suffix=dayNumber.toString(16).padStart(16,'0').slice(-16),hex=prefix+suffix;return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;}
function billDueLabel(dueDate){const todayKey=dateInputValue(new Date());if(dueDate<todayKey)return 'Overdue · '+prettyDate(dueDate,true);if(dueDate===todayKey)return 'Due today';return 'Due '+prettyDate(dueDate,true);}
function renderUpcomingBills(){const list=$('#upcoming-bills-list');if(!list)return;const pending=data.bills.filter(x=>x.status==='pending').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,3);if(!pending.length){list.innerHTML='<div class="empty-state compact-empty">No pending bills. Add a bill to see what is coming up.</div>';return;}list.innerHTML=pending.map(x=>`<div class="upcoming-bill-row"><span class="bill-dot ${x.dueDate<dateInputValue(new Date())?'overdue':''}"></span><div><b>${escapeHtml(x.name)}</b><small>${billDueLabel(x.dueDate)}</small></div><strong>${money(x.amount)}</strong></div>`).join('');}
function renderReminders(){const panel=$('#reminder-center');if(!panel)return;const reminders=[],now=new Date(),todayKey=dateInputValue(now),soon=new Date(now);soon.setDate(soon.getDate()+2);const soonKey=dateInputValue(soon);if(data.reminderPrefs.billDue){const due=data.bills.filter(x=>x.status==='pending'&&x.dueDate<=soonKey).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));if(due.length){const overdue=due.some(x=>x.dueDate<todayKey);reminders.push(`<div class="reminder-card bill-reminder"><span>▣</span><div><b>${overdue?'A bill is overdue':'A bill is due soon'}</b><small>${due.length===1?escapeHtml(due[0].name)+' · '+money(due[0].amount):due.length+' bills are due within two days'}</small></div><button type="button" class="secondary-button" data-reminder-action="bills">View</button></div>`);}}if(data.reminderPrefs.longShift&&data.activeClock&&Date.now()-new Date(data.activeClock.startedAt).getTime()>=12*60*60*1000){reminders.push('<div class="reminder-card shift-reminder"><span>◷</span><div><b>Your shift timer has been running for 12 hours</b><small>Review the time and clock out if you are done.</small></div><button type="button" class="secondary-button" data-reminder-action="clock">Review</button></div>');}panel.innerHTML=reminders.join('');panel.classList.toggle('hidden',!reminders.length);}
function renderBills(){const list=$('#bills-list');if(!list)return;const pending=data.bills.filter(x=>x.status==='pending');$('#bills-due-total').textContent=money(pending.reduce((sum,x)=>sum+Number(x.amount||0),0));if(!data.bills.length){list.innerHTML='<div class="empty-state"><div class="empty-icon">▣</div><b>No bills saved</b>Add a one-time or recurring bill to see upcoming payments.</div>';return;}list.innerHTML=[...data.bills].sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).map(x=>`<div class="bill-row"><span class="bill-dot ${x.status==='pending'&&x.dueDate<dateInputValue(new Date())?'overdue':''}"></span><div class="bill-main"><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.category)} · ${x.status==='pending'?billDueLabel(x.dueDate):'Due '+prettyDate(x.dueDate,true)} · ${x.frequency==='once'?'One time':'Repeats '+x.frequency}</small>${x.note?`<small>${escapeHtml(x.note)}</small>`:''}</div><div class="bill-amount"><b>${money(x.amount)}</b><small class="bill-status ${x.status}">${x.status}</small></div><div class="bill-actions">${x.status==='pending'?`<button class="row-edit" data-bill-action="paid" data-bill-id="${escapeHtml(x.id)}">Paid</button><button class="row-edit" data-bill-action="skip" data-bill-id="${escapeHtml(x.id)}">Skip</button><button class="row-edit" data-bill-edit="${escapeHtml(x.id)}">Edit</button>`:''}<button class="row-delete" data-delete-kind="bills" data-delete-id="${escapeHtml(x.id)}" aria-label="Delete bill">×</button></div></div>`).join('');}
function openBill(id=null){editingBillId=id;const item=id?data.bills.find(x=>x.id===id):null;$('#bill-dialog-title').textContent=item?'Edit bill':'Add a bill';$('#bill-name').value=item?.name||'';$('#bill-amount').value=item?.amount||'';$('#bill-due-date').value=item?.dueDate||dateInputValue(new Date());$('#bill-category').value=item?.category||'Rent';$('#bill-frequency').value=item?.frequency||'once';$('#bill-payment').value=item?.paymentMethod||'Bank transfer';$('#bill-note').value=item?.note||'';$('#bill-error').textContent='';$('#bill-dialog').showModal();}
function saveBill(event){event.preventDefault();const name=$('#bill-name').value.trim(),amount=Number($('#bill-amount').value),dueDate=$('#bill-due-date').value,error=$('#bill-error');error.textContent='';if(!name||!dueDate||!Number.isInteger(amount)||amount<1){error.textContent='Enter a bill name, due date, and amount in whole rupees.';return;}const current=editingBillId?data.bills.find(x=>x.id===editingBillId):null,anchorDate=parseDay(dueDate),bill={id:current?.id||crypto.randomUUID(),seriesId:current?.seriesId||crypto.randomUUID(),name,amount,dueDate,category:$('#bill-category').value,frequency:$('#bill-frequency').value,status:current?.status||'pending',paymentMethod:$('#bill-payment').value,anchorDay:current?.anchorDay||anchorDate.getDate(),anchorMonth:current?.anchorMonth||anchorDate.getMonth()+1,note:$('#bill-note').value.trim()};if(current){const index=data.bills.findIndex(x=>x.id===current.id);data.bills[index]=bill;}else data.bills.push(bill);editingBillId=null;save();$('#bill-dialog').close();refresh();toast('Bill saved');}
function resolveBill(id,status){const bill=data.bills.find(x=>x.id===id);if(!bill||bill.status!=='pending')return;bill.status=status;if(status==='paid'){data.expenses.push({id:bill.id,amount:Number(bill.amount),date:dateInputValue(new Date()),category:bill.category||'Other',paymentMethod:bill.paymentMethod||'Bank transfer',note:'Bill paid: '+bill.name});}const seriesId=bill.seriesId||bill.id,nextDueDate=nextBillDate(bill.dueDate,bill.frequency,bill.anchorDay,bill.anchorMonth);if(nextDueDate)data.bills.push({id:billOccurrenceId(seriesId,nextDueDate),seriesId,name:bill.name,amount:bill.amount,dueDate:nextDueDate,category:bill.category,frequency:bill.frequency,status:'pending',paymentMethod:bill.paymentMethod||'Bank transfer',anchorDay:bill.anchorDay,anchorMonth:bill.anchorMonth,note:bill.note||''});save();refresh();toast(status==='paid'?'Bill marked paid and added to expenses':'Bill skipped');}
function renderShifts() { const d=monthData();$('#shifts-hours').textContent=`${formatHours(d.hours)} hrs`;$('#shifts-caption').textContent=$('#month-select').selectedOptions[0]?.textContent||'Selected month';
 const weeks=new Map();for(const shift of d.shifts){const start=weekStartFor(shift.date);if(!weeks.has(start))weeks.set(start,[]);weeks.get(start).push(shift);}const weekRows=[...weeks.entries()].sort((a,b)=>b[0].localeCompare(a[0])).map(([start,shifts])=>({start,shifts,hours:shifts.reduce((sum,x)=>sum+shiftHours(x),0)}));const maxHours=Math.max(1,...weekRows.map(x=>x.hours));$('#weekly-list').innerHTML=weekRows.length?weekRows.map(x=>`<div class="week-row"><div class="week-label"><b>${weekRangeLabel(x.start)}</b><small>${x.shifts.length} ${x.shifts.length===1?'shift':'shifts'}</small></div><div class="week-bar"><span style="width:${Math.max(4,x.hours/maxHours*100)}%"></span></div><strong>${formatHours(x.hours)} hrs</strong></div>`).join(''):'<div class="empty-state compact-empty">Log a shift to see weekly totals.</div>';
 const list=$('#shifts-list'); if(!d.shifts.length){list.innerHTML='<div class="empty-state"><div class="empty-icon">◷</div><b>No shifts logged yet</b>Your shifts will show up here when you add them.</div>';return;}
 const days=new Map();for(const shift of d.shifts){if(!days.has(shift.date))days.set(shift.date,[]);days.get(shift.date).push(shift);}list.innerHTML=[...days.entries()].sort((a,b)=>b[0].localeCompare(a[0])).map(([date,shifts])=>`<div class="day-group"><div class="day-group-heading"><b>${prettyDate(date,true)}</b><span>${formatHours(shifts.reduce((sum,x)=>sum+shiftHours(x),0))} hrs</span></div>${shifts.sort((a,b)=>a.start.localeCompare(b.start)).map(x=>`<div class="list-entry"><span class="activity-icon shift">◷</span><div class="entry-main"><b>${escapeHtml(x.workplace||'Work shift')}</b><small>${x.start}–${x.end}${Number(x.breakMinutes)?` · ${x.breakMinutes}m break`:''}</small></div><div class="entry-right"><b>+ ${money(shiftPay(x))}</b><small>${formatHours(shiftHours(x))} hrs · estimate</small></div><button class="row-edit" data-edit-kind="shifts" data-edit-id="${x.id}" aria-label="Edit shift">Edit</button><button class="row-delete" data-delete-kind="shifts" data-delete-id="${x.id}" aria-label="Delete shift">×</button></div>`).join('')}</div>`).join(''); }
function escapeHtml(value='') { return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function cloudStatus(message,error=''){const status=$('#cloud-status'),errorEl=$('#cloud-error');if(status)status.textContent=message;if(errorEl)errorEl.textContent=error;}
function showSignedInStatus(){const notices=[];if(!templatesCloudAvailable)notices.push('Templates are device-only until their migration is applied.');if(!incomeCloudAvailable)notices.push('Extra income is device-only until its migration is applied.');if(!payslipsCloudAvailable)notices.push('Payslips are device-only until their migration is applied.');if(!billsCloudAvailable)notices.push('Bills are device-only until their migration is applied.');cloudStatus('Signed in as '+cloudUser.email,notices.join(' '));}
