function rowToPayslip(row){return {id:row.id,workplaceId:row.workplace_id,periodStart:row.period_start,periodEnd:row.period_end,payDate:row.pay_date||'',gross:Number(row.gross_amount),net:Number(row.net_amount),note:row.note||''};}
