function billToRow(x){return {id:x.id,user_id:cloudUser.id,series_id:x.seriesId,name:x.name,amount:Number(x.amount),category:x.category,due_date:x.dueDate,frequency:x.frequency,status:x.status,payment_method:x.paymentMethod||'Bank transfer',anchor_day:x.anchorDay||parseDay(x.dueDate).getDate(),anchor_month:x.anchorMonth||parseDay(x.dueDate).getMonth()+1,note:x.note||'',deleted_at:null};}
