function renderWorkplaceOptions(selectedId='', legacyName='') { const select=$('#workplace'); const options=data.workplaces.map(w=>`<option value="${escapeHtml(w.id)}">${escapeHtml(w.name)} · ${money(w.rate)}/hr</option>`); if(legacyName&&!data.workplaces.some(w=>w.name===legacyName))options.unshift(`<option value="legacy">${escapeHtml(legacyName)} · saved shift rate</option>`); if(!options.length)options.push('<option value="">Add a workplace in Settings first</option>'); select.innerHTML=options.join(''); select.value=selectedId||data.defaultWorkplaceId||select.options[0]?.value||''; }
