function saveEntry(event) {
 event.preventDefault();const error=$('#form-error');error.textContent='';
 if(entryType==='shift'){
  const workplaceId=$('#workplace').value,workplace=data.workplaces.find(w=>w.id===workplaceId),date=$('#shift-date').value,start=$('#start-time').value,end=$('#end-time').value,rate=Number($('#rate').value),breakMinutes=Number($('#break-minutes').value)||0,tips=Number($('#tips').value)||0;
  if(!workplace){error.textContent='Add a workplace in Settings before saving this shift.';return;}
  if(!date||!start||!end||rate<=0){error.textContent='Add a date, start and end time, and a rate above zero.';return;}
  if(breakMinutes<0||breakMinutes>600||shiftDuration({start,end,breakMinutes})<=0){error.textContent='Check the break length and shift times.';return;}
  const shift={id:editRecordId||crypto.randomUUID(),workplaceId:workplace.id,workplace:workplace.name,date,start,end,breakMinutes,rate,tips,note:$('#shift-note').value.trim()};
  const overlapping=findOverlappingShift(shift),overlapKey=`${workplace.id}|${date}|${start}|${end}`;
  if(overlapping&&pendingOverlapKey!==overlapKey){pendingOverlapKey=overlapKey;error.textContent=`This overlaps a saved shift (${prettyDate(overlapping.date,true)}, ${overlapping.start}–${overlapping.end}). Save again to keep both shifts.`;$('#save-entry').innerHTML='Save anyway <span>→</span>';return;}
  const wasEdit=Boolean(editRecordId);if(editRecordId){const index=data.shifts.findIndex(x=>x.id===editRecordId);if(index>=0)data.shifts[index]=shift;}else data.shifts.push(shift);
  data.defaultWorkplaceId=workplace.id;data.workplace=workplace.name;data.rate=workplace.rate;if(clockOutPending){data.activeClock=null;clockOutPending=false;}save();$('#entry-dialog').close();refresh();editRecordId=null;pendingOverlapKey=null;toast(`Shift ${wasEdit?'updated':'saved'} · ${formatHours(shiftHours(shift))} hours · ${money(shiftPay(shift))} estimate`);
 }else if(entryType==='income'){
  const amount=Number($('#income-amount').value),date=$('#income-date').value,type=$('#income-type').value,workplaceId=$('#income-workplace').value;if(!Number.isInteger(amount)||amount<=0||!date){error.textContent='Enter an amount in whole rupees and choose a date.';return;}const income={id:editRecordId||crypto.randomUUID(),amount,date,type,workplaceId,note:$('#income-note').value.trim()},wasEdit=Boolean(editRecordId);if(editRecordId){const index=data.incomeEntries.findIndex(x=>x.id===editRecordId);if(index>=0)data.incomeEntries[index]=income;}else data.incomeEntries.push(income);save();$('#entry-dialog').close();refresh();if(activePage==='insights')renderIncomeEntries();editRecordId=null;toast(wasEdit?'Income updated':'Income saved');
 }else{
  const amount=Number($('#amount').value),date=$('#expense-date').value;if(!Number.isInteger(amount)||amount<=0||!date){error.textContent='Enter an amount in whole rupees and choose a date.';return;}
  const expense={id:editRecordId||crypto.randomUUID(),amount,date,category:$('#category').value,paymentMethod:$('#payment-method').value,note:$('#expense-note').value.trim()},wasEdit=Boolean(editRecordId);if(editRecordId){const index=data.expenses.findIndex(x=>x.id===editRecordId);if(index>=0)data.expenses[index]=expense;}else data.expenses.push(expense);save();$('#entry-dialog').close();refresh();editRecordId=null;toast(wasEdit?'Expense updated':'Expense saved');
 }
}
function clearOverlapWarning(){if(!pendingOverlapKey)return;pendingOverlapKey=null;$('#form-error').textContent='';$('#save-entry').innerHTML=(editRecordId?'Save changes':'Save shift')+' <span>→</span>';}
function exportCsv(){const rows=[['type','date','description','hours','amount_rs','payment_method','note']];data.shifts.forEach(x=>rows.push(['shift estimate',x.date,x.workplace,shiftHours(x).toFixed(2),shiftPay(x),'',x.note||'']));data.incomeEntries.forEach(x=>rows.push([x.type,x.date,data.workplaces.find(w=>w.id===x.workplaceId)?.name||'', '',x.amount,'',x.note||'']));data.payslips.forEach(x=>rows.push(['payslip gross',x.periodEnd,data.workplaces.find(w=>w.id===x.workplaceId)?.name||'', '',x.gross,'',`Period ${x.periodStart} to ${x.periodEnd}; net ${x.net}`]));data.bills.forEach(x=>rows.push([`bill ${x.status}`,x.dueDate,x.name,'',x.amount,'',`${x.frequency}; ${x.category}${x.note?'; '+x.note:''}`]));data.expenses.forEach(x=>rows.push(['expense',x.date,x.category,'',x.amount,x.paymentMethod||'Cash',x.note||'']));const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='shiftly-export.csv';a.click();URL.revokeObjectURL(url);toast('Your CSV is ready');}
function downloadJsonBackup(){const backup={format:'shiftly-backup',version:1,createdAt:new Date().toISOString(),data};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='shiftly-backup-'+dateInputValue(new Date())+'.json';a.click();URL.revokeObjectURL(url);toast('Backup downloaded');}
async function restoreJsonBackup(file){const error=$('#backup-error');error.textContent='';try{const backup=JSON.parse(await file.text()),restored=backup?.data;if(backup?.format!=='shiftly-backup'||backup.version!==1||!restored||!Array.isArray(restored.shifts)||!Array.isArray(restored.expenses)||!Array.isArray(restored.workplaces))throw new Error('This file is not a supported Shiftly backup.');if(!restored.shifts.every(x=>x&&typeof x.date==='string'&&typeof x.start==='string'&&typeof x.end==='string')||!restored.expenses.every(x=>x&&typeof x.date==='string'&&Number.isFinite(Number(x.amount)))||!restored.workplaces.every(x=>x&&typeof x.name==='string'&&Number.isFinite(Number(x.rate)))||!(restored.incomeEntries||[]).every(x=>x&&typeof x.date==='string'&&Number.isFinite(Number(x.amount))&&typeof x.type==='string')||!(restored.payslips||[]).every(x=>x&&typeof x.periodStart==='string'&&typeof x.periodEnd==='string'&&Number.isFinite(Number(x.gross))&&Number.isFinite(Number(x.net)))||!(restored.bills||[]).every(x=>x&&typeof x.name==='string'&&typeof x.dueDate==='string'&&Number.isFinite(Number(x.amount))))throw new Error('The backup contains invalid entries.');if(!window.confirm('Restore '+restored.shifts.length+' shifts, '+restored.expenses.length+' expenses, '+(restored.incomeEntries||[]).length+' income entries, '+(restored.payslips||[]).length+' payslips, '+(restored.bills||[]).length+' bills, and '+restored.workplaces.length+' workplaces? This replaces the data currently saved in this browser.'))return;data={...initial,...restored,shifts:restored.shifts,expenses:restored.expenses,incomeEntries:restored.incomeEntries||[],payslips:restored.payslips||[],bills:restored.bills||[],workplaces:restored.workplaces};if(!data.defaultWorkplaceId||!data.workplaces.some(x=>x.id===data.defaultWorkplaceId))data.defaultWorkplaceId=data.workplaces[0]?.id||'';const workplace=data.workplaces.find(x=>x.id===data.defaultWorkplaceId);if(workplace){data.workplace=workplace.name;data.rate=workplace.rate;}save();renderSettings();renderReminderPrefs();refresh();error.textContent='';toast('Backup restored');}catch(err){error.textContent=err.message||'Could not read that backup file.';}finally{$('#backup-file').value='';}}
function deleteRecord(kind,id){const index=data[kind].findIndex(x=>x.id===id);if(index<0)return;const [item]=data[kind].splice(index,1);save();refresh();toast('Record removed',()=>{data[kind].splice(index,0,item);save();refresh();toast('Record restored');});}
function saveSettings(event){event.preventDefault();const wasEdit=Boolean(editingWorkplaceId),name=$('#settings-workplace').value.trim(),rate=Number($('#settings-rate').value),duplicate=data.workplaces.find(w=>w.name.toLocaleLowerCase()===name.toLocaleLowerCase()&&w.id!==editingWorkplaceId);if(!name){toast('Add a workplace name');return;}if(!Number.isInteger(rate)||rate<1){toast('Enter a whole rupee rate above zero');return;}if(duplicate){toast('That workplace is already saved');return;}let workplace;if(editingWorkplaceId){workplace=data.workplaces.find(w=>w.id===editingWorkplaceId);if(!workplace)return;workplace.name=name;workplace.rate=rate;}else{workplace={id:crypto.randomUUID(),name,rate};data.workplaces.push(workplace);data.defaultWorkplaceId=workplace.id;}if(data.defaultWorkplaceId===workplace.id){data.workplace=name;data.rate=rate;}save();resetWorkplaceForm();renderSettings();toast(wasEdit?'Workplace updated':'Workplace added');}
function resetWorkplaceForm(){editingWorkplaceId=null;$('#settings-workplace').value='';$('#settings-rate').value='';$('#workplace-save').innerHTML='Add workplace <span>＋</span>';$('#workplace-cancel').classList.add('hidden');}
function editWorkplace(id){const workplace=data.workplaces.find(w=>w.id===id);if(!workplace)return;editingWorkplaceId=id;$('#settings-workplace').value=workplace.name;$('#settings-rate').value=workplace.rate;$('#workplace-save').innerHTML='Save changes <span>→</span>';$('#workplace-cancel').classList.remove('hidden');$('#settings-workplace').focus();}
