function renderSettings(){const list=$('#workplaces-list');if(!data.workplaces.length){list.innerHTML='<div class="empty-state"><div class="empty-icon">◷</div><b>No workplaces saved</b>Add a workplace and hourly rate to start logging shifts.</div>';}else list.innerHTML=data.workplaces.map(w=>`<div class="workplace-row"><div class="workplace-details"><b>${escapeHtml(w.name)}</b><small>${money(w.rate)} per hour${w.id===data.defaultWorkplaceId?' · Default':''}</small></div><div class="workplace-actions"><button class="row-edit" data-workplace-edit="${w.id}">Edit</button>${w.id===data.defaultWorkplaceId?'':'<button class="row-edit" data-workplace-default="'+w.id+'">Set default</button>'}</div></div>`).join('');const select=$('#template-workplace');select.innerHTML=data.workplaces.map(w=>`<option value="${escapeHtml(w.id)}">${escapeHtml(w.name)}</option>`).join('')||'<option value="">Add a workplace first</option>';$('#template-form button[type="submit"]').disabled=!data.workplaces.length;const templates=$('#templates-list');templates.innerHTML=data.shiftTemplates.length?data.shiftTemplates.map(t=>{const w=data.workplaces.find(x=>x.id===t.workplaceId);return `<div class="workplace-row"><div class="workplace-details"><b>${escapeHtml(t.name)}</b><small>${escapeHtml(w?.name||'Workplace unavailable')} · ${t.start}–${t.end} · ${t.breakMinutes}m break</small></div><div class="workplace-actions"><button type="button" class="row-edit" data-template-use="${escapeHtml(t.id)}">Use</button><button type="button" class="row-delete" data-template-delete="${escapeHtml(t.id)}" aria-label="Delete template">×</button></div></div>`;}).join(''):'<p class="settings-copy">No templates saved yet.</p>';}
function saveShiftTemplate(event){event.preventDefault();const name=$('#template-name').value.trim(),workplaceId=$('#template-workplace').value,start=$('#template-start').value,end=$('#template-end').value,breakMinutes=Number($('#template-break').value)||0;if(!name||!workplaceId||!start||!end||start===end||breakMinutes<0||breakMinutes>600){toast('Enter a name, workplace, and valid shift times');return;}if(data.shiftTemplates.some(t=>t.name.toLocaleLowerCase()===name.toLocaleLowerCase())){toast('A template with that name already exists');return;}data.shiftTemplates.push({id:crypto.randomUUID(),name,workplaceId,start,end,breakMinutes});save();renderSettings();$('#template-name').value='';toast('Shift template saved');}
function useShiftTemplate(id){const template=data.shiftTemplates.find(x=>x.id===id);if(!template)return;openEntry('shift');$('#workplace').value=template.workplaceId;const workplace=data.workplaces.find(x=>x.id===template.workplaceId);if(workplace)$('#rate').value=workplace.rate;$('#start-time').value=template.start;$('#end-time').value=template.end;$('#break-minutes').value=template.breakMinutes;calcPreview();}
